import pathlib,json,hashlib,subprocess,time,platform,importlib.metadata
R=pathlib.Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def cmd(a):
 p=subprocess.run(a,cwd=R,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True);return {'argv':a,'exit_code':p.returncode,'output':p.stdout.strip()}
repos={}
for name in ['Deagle','results','sv-benchmarks','bench-defs','sv-witnesses']:
 p=R/'sources'/name
 repos[name]={'commit':cmd(['git','-C',str(p),'rev-parse','HEAD']),'origin':cmd(['git','-C',str(p),'remote','get-url','origin']),'status':cmd(['git','-C',str(p),'status','--porcelain']),'describe':cmd(['git','-C',str(p),'describe','--always','--tags','--dirty'])}
runtime={}
for args in [['/tool/deagle','--version'],['/tool/deagle_exe','--version'],['/usr/bin/python3','--version'],['/usr/bin/gcc','--version'],['/usr/lib/x86_64-linux-gnu/libc.so.6']]:runtime[args[0]]=cmd(['/usr/sbin/chroot',str(R/'runtime/rootfs')]+args)
files={str(p.relative_to(R)):{'bytes':p.stat().st_size,'sha256':sha(p)} for root in ['scripts','sources/official-tool','sources/python-deps/benchexec/tools'] for p in (R/root).rglob('*') if p.is_file() and (root!='sources/python-deps/benchexec/tools' or p.name=='deagle.py') and '__pycache__' not in p.parts and '.git' not in p.parts}
for p in [R/'archives/deagle-localmirror.zip',R/'runtime/rootfs/tool/deagle',R/'runtime/rootfs/tool/deagle_exe',R/'runtime/packages/packages-manifest.json',R/'runtime/delta/packages-manifest.json']:
 if p.exists():files[str(p.relative_to(R))]={'bytes':p.stat().st_size,'sha256':sha(p)}
out={'recorded_utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'server_dedicated_directory':str(R),'execution_kind':'official competition binary, not a source rebuild','repositories':repos,'runtime':runtime,'files':files,'host':{'uname':cmd(['uname','-a']),'lscpu':cmd(['lscpu']),'python':platform.python_version(),'kernel':platform.release()},'official_binary_source_relation':'Launcher byte-identical to source commit 759aed5e9f107bf3c1ff1c7ff51c5760c55409b4. Binary embeds CBMC POPL26-exp-8-ga6ad3e6a8-dirty; exact clean source provenance cannot be attested from that string. No rebuild was used.','benchexec':{'version':'3.32','tag_commit':'b3a114620e7f7972fcd816a3bf0e42d2977a42fe','selection_reason':'Actual Deagle original XML reports 3.32. Annual reproduction page mentions 3.34.'},'resource_policy':{'soft_cpu_seconds':900,'hard_cpu_seconds':960,'memory_bytes':15000000000,'kernel_memory_max_bytes':14999998464,'workers':7,'cpus_per_run':4,'cpu_sets':[[4+i*4+j for j in range(4)] for i in range(7)],'observer_and_diagnostics_cpu_set':[0,1,2,3],'swap_bytes':0,'aggregate_memory_peak':'unavailable on kernel 5.15; ~20ms sampled memory.current lower bound plus per-process wait4 maxrss are recorded','observed_timeout_policy_difference':'Official 35 TIMEOUT records: about 961 CPU seconds, signal 9, cputime. Local original-parameter run: about 900 CPU seconds, cputime-soft. Same nominal 900/960 configuration does not reproduce VCloud termination behavior exactly. Separate hard960-policy diagnostics are explicitly outside the 900-second baseline.'},'scope':'Only the dedicated directory and ephemeral own cgroups/mount namespaces/systemd units used. No host OS packages or preexisting server files changed.'}
out['python_dependency_versions']={name:sorted([{'name':d.metadata['Name'],'version':d.version} for d in importlib.metadata.distributions(path=[str(R/'sources'/name)])],key=lambda d:d['name']) for name in ['python-deps','linter-deps']}
(R/'reports/provenance.json').write_text(json.dumps(out,ensure_ascii=False,indent=2));print('PROVENANCE',len(files),'files')
